def solve(n, k, start, end):
	tot = 0
	lvl = 1
	for i in range(n):
		lvl += lvl - int(start[i] == 'b') - int(end[i] == 'a')
		if lvl >= k:
			tot += k * (n - i)
			break
		else:
			tot += lvl
	return tot
(n, k) = map(int, input().split())
start = input()
end = input()
print(solve(n, k, start, end))
